package com.alsafa.native4;

import android.app.Activity;import android.content.Intent;import android.graphics.Bitmap;import android.graphics.Color;import android.net.Uri;import android.provider.MediaStore;import android.text.Editable;import android.text.InputType;import android.text.TextWatcher;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.DirectRepairPartSaleStore;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.RepairPartReservationStore;import com.alsafa.native4.core.RepairPartStore;import com.alsafa.native4.core.QuickRepairButtonStore;import com.alsafa.native4.core.SplitPaymentStore;import java.io.File;import java.io.FileOutputStream;import java.net.URLEncoder;import java.util.ArrayList;import java.util.List;
/** Searchable multi-part quick repair. Immediate handover and leave-watch both support several parts in one operation. */
public final class DirectPartSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final LinearLayout panel,partsBox,paymentSection,leaveDetails;private final EditText serviceFee,customerName,customerPhone,watchNote;private final Spinner currency,handover;private final TextView photoStatus;private String pendingPhotoUri="",pendingPhotoSource="";public static final int REQ_REPAIR_CAMERA=7401,REQ_REPAIR_GALLERY=7402;
 public DirectPartSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);TextView title=new TextView(a);title.setText("الصيانة السريعة");title.setTextSize(20);title.setGravity(Gravity.END);panel.addView(title);TextView help=new TextView(a);help.setText("ابحث بالاسم أو الباركود، واختر أكثر من قطعة في نفس العملية. يعمل ذلك سواء استلم العميل الساعة فورًا أو تركها لدينا.");help.setGravity(Gravity.END);panel.addView(help);LinearLayout quickBox=new LinearLayout(a);quickBox.setOrientation(LinearLayout.VERTICAL);TextView quickTitle=new TextView(a);quickTitle.setText("⚡ الأزرار السريعة");quickTitle.setTextSize(18);quickTitle.setGravity(Gravity.END);quickBox.addView(quickTitle);Button manageQuick=new Button(a);manageQuick.setText("⚙️ إدارة وربط الأزرار السريعة");manageQuick.setBackgroundResource(R.drawable.alsafa_card);manageQuick.setOnClickListener(v->a.startActivity(new Intent(a,QuickRepairButtonsActivity.class)));quickBox.addView(manageQuick);List<QuickRepairButtonStore.Item> quickItems=services.quickRepairButtons.active();if(quickItems.isEmpty()){TextView empty=new TextView(a);empty.setText("لا توجد أزرار سريعة مرتبطة بقطع الصيانة بعد.");empty.setGravity(Gravity.END);quickBox.addView(empty);}else{LinearLayout row=null;for(int i=0;i<quickItems.size();i++){if(i%2==0){row=new LinearLayout(a);row.setOrientation(LinearLayout.HORIZONTAL);quickBox.addView(row);}QuickRepairButtonStore.Item qi=quickItems.get(i);Button qb=new Button(a);qb.setAllCaps(false);qb.setText(qi.icon+" "+qi.label+"\nالمتاح "+qi.quantity+(qi.salePrice>0?" — "+fmt(qi.salePrice)+" "+qi.currency:""));qb.setMinHeight(dp(72));qb.setBackgroundResource(R.drawable.alsafa_card);qb.setOnClickListener(v->addQuickPart(qi));row.addView(qb,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));}}panel.addView(quickBox);partsBox=new LinearLayout(a);partsBox.setOrientation(LinearLayout.VERTICAL);panel.addView(partsBox);Button addPart=new Button(a);addPart.setText("+ إضافة قطعة أخرى");styleSecondary(addPart);addPart.setOnClickListener(v->addPartRow());panel.addView(addPart);addPartRow();serviceFee=field(a,"أجرة الخدمة الإجمالية (اختياري)",numType());currency=new Spinner(a);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));styleSpinner(currency);panel.addView(serviceFee);panel.addView(currency);handover=new Spinner(a);handover.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"تم التسليم — استلم العميل الساعة فورًا","ترك الساعة لدينا — بدون تحصيل الآن"}));styleSpinner(handover);panel.addView(handover);leaveDetails=new LinearLayout(a);leaveDetails.setOrientation(LinearLayout.VERTICAL);customerName=field(a,"اسم العميل",InputType.TYPE_CLASS_TEXT);customerPhone=field(a,"رقم الهاتف",InputType.TYPE_CLASS_PHONE);watchNote=field(a,"وصف الساعة / سبب تركها",InputType.TYPE_CLASS_TEXT);leaveDetails.addView(customerName);leaveDetails.addView(customerPhone);leaveDetails.addView(watchNote);LinearLayout photoButtons=new LinearLayout(a);photoButtons.setOrientation(LinearLayout.HORIZONTAL);Button camera=new Button(a);camera.setText("📷 التقاط صورة");camera.setOnClickListener(v->openCamera());Button gallery=new Button(a);gallery.setText("🖼 اختيار من الاستوديو");gallery.setOnClickListener(v->openGallery());photoButtons.addView(camera,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));photoButtons.addView(gallery,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));leaveDetails.addView(photoButtons);photoStatus=new TextView(a);photoStatus.setText("لم يتم اختيار صورة بعد");photoStatus.setGravity(Gravity.END);leaveDetails.addView(photoStatus);leaveDetails.setVisibility(View.GONE);panel.addView(leaveDetails);paymentSection=new LinearLayout(a);paymentSection.setOrientation(LinearLayout.VERTICAL);TextView paymentLabel=new TextView(a);paymentLabel.setText("الدفعات — مبلغ وعملة ومكان التحصيل");paymentLabel.setGravity(Gravity.END);paymentSection.addView(paymentLabel);Button addPayment=new Button(a);addPayment.setText("+ إضافة دفعة أخرى");addPayment.setOnClickListener(v->addPaymentRow());paymentSection.addView(addPayment);panel.addView(paymentSection);addPaymentRow();handover.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){boolean left=pos==1;leaveDetails.setVisibility(left?View.VISIBLE:View.GONE);paymentSection.setVisibility(left?View.GONE:View.VISIBLE);}public void onNothingSelected(android.widget.AdapterView<?> p){}});Button save=new Button(a);save.setText("✓ تثبيت الصيانة السريعة");save.setMinHeight(dp(62));save.setTextColor(Color.WHITE);save.setTextSize(18);save.setBackgroundResource(R.drawable.alsafa_primary);save.setOnClickListener(v->save());panel.addView(save);host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}
 public void selectQuickPart(String partId){RepairPartStore.SearchResult r=services.repairParts.get(partId);if(r==null){status.setText("قطعة الصيانة المرتبطة بالزر غير موجودة");return;}addExactPart(r);}
 private void addExactPart(RepairPartStore.SearchResult r){addPartRow();View box=partsBox.getChildAt(partsBox.getChildCount()-1);PartViews pv=(PartViews)box.getTag();pv.search.setText(r.name);pv.items.clear();pv.items.add(r);ArrayList<String> labels=new ArrayList<>();labels.add(r.name+" — المتاح "+r.quantity+(r.barcode==null||r.barcode.isEmpty()?"":" — "+r.barcode));pv.results.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));pv.results.setSelection(0);if(r.salePrice>0)pv.price.setText(fmt(r.salePrice));status.setText("✓ تمت إضافة "+r.name+" إلى العملية");}
 public void onActivityResult(int requestCode,int resultCode,Intent data){if(resultCode!=Activity.RESULT_OK)return;try{if(requestCode==REQ_REPAIR_GALLERY&&data!=null&&data.getData()!=null){Uri u=data.getData();try{a.getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}pendingPhotoUri=u.toString();pendingPhotoSource="GALLERY";photoStatus.setText("✓ تم اختيار صورة من الاستوديو");}else if(requestCode==REQ_REPAIR_CAMERA&&data!=null&&data.getExtras()!=null&&data.getExtras().get("data") instanceof Bitmap){Bitmap b=(Bitmap)data.getExtras().get("data");File dir=new File(a.getFilesDir(),"repair_photos");if(!dir.exists()&&!dir.mkdirs())throw new IllegalStateException("تعذر إنشاء مجلد صور الصيانة");File out=new File(dir,"repair-"+System.currentTimeMillis()+".jpg");try(FileOutputStream fos=new FileOutputStream(out)){b.compress(Bitmap.CompressFormat.JPEG,90,fos);}pendingPhotoUri=Uri.fromFile(out).toString();pendingPhotoSource="CAMERA";photoStatus.setText("✓ تم التقاط صورة الاستلام");}}catch(Exception e){status.setText("تعذر حفظ صورة الصيانة: "+msg(e));}}
 private void openCamera(){try{Intent i=new Intent(MediaStore.ACTION_IMAGE_CAPTURE);a.startActivityForResult(i,REQ_REPAIR_CAMERA);}catch(Exception e){status.setText("تعذر فتح الكاميرا: "+msg(e));}}
 private void openGallery(){try{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);a.startActivityForResult(i,REQ_REPAIR_GALLERY);}catch(Exception e){status.setText("تعذر فتح الاستوديو: "+msg(e));}}
 private void openWhatsApp(String phone,String repairId){try{String p=phone.replaceAll("[^0-9+]","");if(p.startsWith("0"))p="963"+p.substring(1);else if(p.startsWith("+"))p=p.substring(1);String message="شكرًا لاختياركم الصفا للساعات. تم استلام ساعتكم للصيانة. رقم العملية: "+repairId+" وسنبلغكم عند الجاهزية.";Uri u=Uri.parse("https://wa.me/"+p+"?text="+URLEncoder.encode(message,"UTF-8"));a.startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception e){status.setText("تم حفظ الصيانة، لكن تعذر فتح واتساب: "+msg(e));}}
 private void addQuickPart(QuickRepairButtonStore.Item qi){addPartRow();View box=partsBox.getChildAt(partsBox.getChildCount()-1);PartViews pv=(PartViews)box.getTag();pv.search.setText(qi.partName);refreshPartResults(pv,qi.partName);for(int i=0;i<pv.items.size();i++)if(qi.partId.equals(pv.items.get(i).partId)){pv.results.setSelection(i);if(pv.price.getText().toString().trim().isEmpty()&&qi.salePrice>0)pv.price.setText(fmt(qi.salePrice));break;}status.setText("✓ تمت إضافة "+qi.label+" إلى العملية");}
 private void addPartRow(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText search=field(a,"بحث عن قطعة: الاسم أو الباركود",InputType.TYPE_CLASS_TEXT);Spinner results=new Spinner(a);EditText qty=field(a,"الكمية",InputType.TYPE_CLASS_NUMBER);qty.setText("1");EditText price=field(a,"سعر هذه القطعة للعميل",numType());Button remove=new Button(a);remove.setText("حذف القطعة");PartViews pv=new PartViews(search,results,qty,price);box.setTag(pv);box.addView(search);box.addView(results);box.addView(qty);box.addView(price);box.addView(remove);remove.setOnClickListener(v->{if(partsBox.getChildCount()>1)partsBox.removeView(box);else{search.setText("");qty.setText("1");price.setText("");pv.items.clear();results.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"اكتب للبحث"}));}});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){search.removeCallbacks(pv.searchTask);pv.searchTask=()->refreshPartResults(pv,s.toString());search.postDelayed(pv.searchTask,325);}public void afterTextChanged(Editable e){}});results.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"اكتب للبحث"}));partsBox.addView(box);}
 private void refreshPartResults(PartViews pv,String q){pv.items.clear();List<RepairPartStore.SearchResult> found=services.repairParts.search(q,20);pv.items.addAll(found);ArrayList<String> labels=new ArrayList<>();if(found.isEmpty())labels.add(q.trim().isEmpty()?"اكتب للبحث":"لا توجد نتائج");else for(RepairPartStore.SearchResult r:found)labels.add(r.name+" — المتاح "+services.repairPartReservations.available(r.partId)+(r.barcode==null||r.barcode.isEmpty()?"":" — "+r.barcode));pv.results.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));if(found.size()==1&&pv.price.getText().toString().trim().isEmpty()&&found.get(0).salePrice>0)pv.price.setText(fmt(found.get(0).salePrice));}
 private List<PartSelection> readParts(){ArrayList<PartSelection> out=new ArrayList<>();for(int i=0;i<partsBox.getChildCount();i++){PartViews p=(PartViews)partsBox.getChildAt(i).getTag();if(p.items.isEmpty())throw new IllegalArgumentException("اختر نتيجة صحيحة لكل قطعة");int pos=p.results.getSelectedItemPosition();if(pos<0||pos>=p.items.size())throw new IllegalArgumentException("اختر قطعة من نتائج البحث");RepairPartStore.SearchResult r=p.items.get(pos);int q=Integer.parseInt(p.qty.getText().toString().trim());if(q<=0)throw new IllegalArgumentException("كمية القطعة غير صحيحة");double price=num(p.price);out.add(new PartSelection(r,q,price));}return out;}
 private void addPaymentRow(){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field(a,"المبلغ المقبوض",numType());Spinner cur=new Spinner(a);cur.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));Spinner account=new Spinner(a);account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"}));Button remove=new Button(a);remove.setText("حذف الدفعة");box.addView(amount);box.addView(cur);box.addView(account);box.setTag(new PaymentViews(amount,cur,account));box.addView(remove);remove.setOnClickListener(v->{int rows=0;for(int i=0;i<paymentSection.getChildCount();i++)if(paymentSection.getChildAt(i).getTag() instanceof PaymentViews)rows++;if(rows>1)paymentSection.removeView(box);else amount.setText("");});paymentSection.addView(box);}
 private List<SplitPaymentStore.Payment> readPayments(){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<paymentSection.getChildCount();i++){View v=paymentSection.getChildAt(i);if(!(v.getTag() instanceof PaymentViews))continue;PaymentViews p=(PaymentViews)v.getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;double amount=Double.parseDouble(raw);String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,p.currency.getSelectedItemPosition());String acc=accountCode(p.account.getSelectedItemPosition());if("SHAM_CASH".equals(acc)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");out.add(new SplitPaymentStore.Payment(amount,cur,"SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH",acc));}return out;}
 private void save(){try{List<PartSelection> parts=readParts();double fee=num(serviceFee),partsTotal=0;for(PartSelection x:parts)partsTotal+=x.price*x.qty;double agreed=partsTotal+fee;String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition());boolean left=handover.getSelectedItemPosition()==1;if(left){String name=customerName.getText().toString().trim(),phone=customerPhone.getText().toString().trim(),note=watchNote.getText().toString().trim();if(name.isEmpty())throw new IllegalArgumentException("اسم العميل مطلوب عند ترك الساعة لدينا");if(phone.isEmpty())throw new IllegalArgumentException("رقم الهاتف مطلوب عند ترك الساعة لدينا");ArrayList<RepairPartReservationStore.Request> reqs=new ArrayList<>();for(PartSelection x:parts)reqs.add(new RepairPartReservationStore.Request(x.part.partId,x.qty));for(RepairPartReservationStore.Request r:reqs)if(services.repairPartReservations.available(r.partId)<r.quantity)throw new IllegalArgumentException("الرصيد المتاح غير كافٍ للقطعة "+r.partId);String repairId=services.repairs.receive(name,phone,note.isEmpty()?"صيانة سريعة — عدة قطع":note,agreed,cur,"LATER");services.repairPartReservations.reserveAll(repairId,reqs);if(!pendingPhotoUri.isEmpty())services.repairMedia.add(repairId,pendingPhotoUri,pendingPhotoSource);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();String savedPhone=phone;reset();status.setText("✓ تم ترك الساعة لدينا — لا تحصيل الآن — تم حجز "+parts.size()+" نوع/أنواع من القطع — "+repairId);openWhatsApp(savedPhone,repairId);return;}List<SplitPaymentStore.Payment> payments=readPayments();if(payments.isEmpty()&&agreed>0)throw new IllegalArgumentException("أدخل دفعة واحدة على الأقل عند التسليم الفوري");ArrayList<DirectRepairPartSaleStore.Line> lines=new ArrayList<>();for(PartSelection x:parts)lines.add(new DirectRepairPartSaleStore.Line(x.part.partId,x.qty,x.price));DirectRepairPartSaleStore.Result result=services.directPartSales.sellMulti(lines,fee,cur,payments);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();reset();status.setText("✓ تم التسليم فورًا — عملية واحدة — "+parts.size()+" نوع/أنواع — الإجمالي "+fmt(result.total)+" "+result.currency+" — الدفعات "+result.paymentCount);}catch(Exception e){status.setText("لم تُحفظ الصيانة السريعة: "+msg(e));}}
 private void reset(){partsBox.removeAllViews();addPartRow();serviceFee.setText("");customerName.setText("");customerPhone.setText("");watchNote.setText("");pendingPhotoUri="";pendingPhotoSource="";photoStatus.setText("لم يتم اختيار صورة بعد");handover.setSelection(0);for(int i=0;i<paymentSection.getChildCount();i++){View v=paymentSection.getChildAt(i);if(v.getTag() instanceof PaymentViews)((PaymentViews)v.getTag()).amount.setText("");}}
 private static final class PartSelection{final RepairPartStore.SearchResult part;final int qty;final double price;PartSelection(RepairPartStore.SearchResult p,int q,double pr){part=p;qty=q;price=pr;}}private static final class PartViews{final EditText search,qty,price;final Spinner results;final ArrayList<RepairPartStore.SearchResult> items=new ArrayList<>();Runnable searchTask;PartViews(EditText s,Spinner r,EditText q,EditText p){search=s;results=r;qty=q;price=p;}}private static final class PaymentViews{final EditText amount;final Spinner currency,account;PaymentViews(EditText a,Spinner c,Spinner ac){amount=a;currency=c;account=ac;}}
 private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private static EditText field(Activity a,String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setMinHeight(dpStatic(a,54));e.setPadding(dpStatic(a,14),dpStatic(a,8),dpStatic(a,14),dpStatic(a,8));e.setBackgroundResource(R.drawable.alsafa_card);e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private static void styleSpinner(Spinner s){s.setMinimumHeight(dpStatic((Activity)s.getContext(),54));s.setBackgroundResource(R.drawable.alsafa_card);}private static void styleSecondary(Button b){b.setMinHeight(dpStatic((Activity)b.getContext(),54));b.setBackgroundResource(R.drawable.alsafa_card);}
 private static int numType(){return InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL;}private static int dpStatic(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private int dp(int v){return dpStatic(a,v);}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}
